begin; select plan(9); select ok(to_regprocedure('workspace_api.review_items(integer,integer)') is not null and to_regprocedure('workspace_private.review_item_is_authorized(uuid)') is not null,'authorized review functions exist'); select ok((select bool_and(r.rolname='workspace_query_owner') from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid in ('workspace_api.review_items(integer,integer)'::regprocedure,'workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'review functions retain the query owner'); select ok((select bool_and(p.prosecdef) and bool_and(regexp_replace(array_to_string(p.proconfig,','),'\s+','','g') in ('search_path=pg_catalog,workspace_private,public,pg_temp','search_path=pg_catalog,workspace_private,pg_temp')) from pg_proc p where p.oid in ('workspace_api.review_items(integer,integer)'::regprocedure,'workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'review functions are security definers with pinned search paths'); select ok(has_function_privilege('authenticated','workspace_api.review_items(integer,integer)','EXECUTE') and not has_function_privilege('anon','workspace_api.review_items(integer,integer)','EXECUTE') and (to_regrole('service_role') is null or not has_function_privilege('service_role','workspace_api.review_items(integer,integer)','EXECUTE')),'only authenticated reaches the review interface, including an absent service role'); select ok((select d like '%authorized_section_scopes()%' and d like '%frompublic.review_item%' and d like '%resolved_atisnull%' and d like '%limitp_limitoffsetp_offset%' and d like '%pagination_bound%' and d like '%octet_length(payload::text)>120000%' and d not like '%subject_ref%' and d not like '%note%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.review_items(integer,integer)'::regprocedure)),'\s+','','g') d) f),'review list and count are bounded, scope-authorized, and omit personal fields'); select ok((select d like '%review_item_section_scope%' and d like '%authorized_section_scopes()%' and d not like '%platform_only%' from (select regexp_replace(lower(pg_get_functiondef('workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'\s+','','g') d) f),'one structured-section predicate excludes platform-only rows'); select ok((select count(*)=2 and bool_and(qual like '%review_item_is_authorized%') from pg_policies where schemaname='public' and tablename='review_item' and policyname in ('review_item_authenticated_read','workspace_query_owner_review_select')),'authenticated rows and query-owner pagination share the same RLS predicate'); select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.review_item_unresolved_count'::regclass),'legacy count view now obeys the same scoped RLS predicate'); select ok((select indisvalid and indisready from pg_index where indexrelid='public.review_item_authorized_unresolved_idx'::regclass) and (select lower(pg_get_indexdef('public.review_item_authorized_unresolved_idx'::regclass)) like '%resolved_at is null%' and lower(pg_get_indexdef('public.review_item_authorized_unresolved_idx'::regclass)) like '%tenant_scope_state = ''section_scoped''::text%'),'authorized unresolved ordering has a valid partial index'); select * from finish(); rollback;
